#!/usr/bin/env node
// Archive historical single-file builds into reference/builds/<id>/ so every uploaded
// version can be regenerated byte-exactly from the repository (see tools/build-reference.mjs).
//
//   node tools/archive-reference.mjs <build.html> [...more.html]
//
// Large literals shared across the family are replaced by tokens and stored once:
//   @@GLB_B64@@      -> assets/models/ducati916.glb            (base64 re-encoded at build)
//   @@FRONT_ASSET@@  -> assets/tires/front_asset.json          (verbatim JSON text)
//   @@REAR_ASSET@@   -> assets/tires/rear_asset.json
//   @@TIRE_DATA@@    -> reference/data/tire_layered_reference_v633.json.gz (verbatim JSON text, gzip)
// Builds with a virtual file system (window.__DUC_VFS__ = {"path": {"t": "b", "d": "<base64>"}},
// the V84/V85 VOLUMETRICS lineage) keep each file decoded and gzipped under vfs/ (the shared GLB
// becomes @@GLB_B64@@); scripts over 256 KB are stored gzipped (NN.js.gz).
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const sha = (b) => crypto.createHash("sha256").update(b).digest("hex");
const files = process.argv.slice(2);
if (!files.length) {
  console.error("usage: node tools/archive-reference.mjs <build.html> ...");
  process.exit(2);
}
const GLB_B64 = fs.readFileSync(path.join(ROOT, "assets/models/ducati916.glb")).toString("base64");
const FRONT = fs.readFileSync(path.join(ROOT, "assets/tires/front_asset.json"), "utf8");
const REAR = fs.readFileSync(path.join(ROOT, "assets/tires/rear_asset.json"), "utf8");
const DATA_FILE = path.join(ROOT, "reference/data/tire_layered_reference_v633.json.gz");
let TIRE_DATA = fs.existsSync(DATA_FILE) ? zlib.gunzipSync(fs.readFileSync(DATA_FILE)).toString("utf8") : null;

// Find the end of a JSON value that starts at s[i] ('{' or '[') without parsing numbers.
function jsonEnd(s, i) {
  let depth = 0, inStr = false;
  for (let k = i; k < s.length; k++) {
    const c = s.charCodeAt(k);
    if (inStr) {
      if (c === 92) k++; // backslash
      else if (c === 34) inStr = false;
      continue;
    }
    if (c === 34) inStr = true;
    else if (c === 123 || c === 91) depth++;
    else if (c === 125 || c === 93) {
      depth--;
      if (depth === 0) return k + 1;
    }
  }
  throw Error("unterminated JSON literal");
}

// Virtual file system entries -> @@GLB_B64@@ or @@VFS_nn@@ + vfs/nn.gz (decoded bytes).
function tokenizeVfs(body, stats, dir, vfs) {
  const mk = "window.__DUC_VFS__=", i = body.indexOf(mk);
  if (i < 0) return body;
  const a = i + mk.length, b = jsonEnd(body, a), re = /"([^"]+)":\{"t":"(\w)","d":"/g;
  let lit = body.slice(a, b), out = "", last = 0, m;
  while ((m = re.exec(lit))) {
    const st = re.lastIndex, en = lit.indexOf('"', st), b64 = lit.slice(st, en), bytes = Buffer.from(b64, "base64");
    if (bytes.toString("base64") !== b64) throw Error(`VFS ${m[1]}: base64 does not round-trip`);
    let token;
    if (b64 === GLB_B64) token = "@@GLB_B64@@";
    else {
      const n = String(vfs.length).padStart(2, "0");
      token = `@@VFS_${n}@@`;
      fs.mkdirSync(path.join(dir, "vfs"), { recursive: true });
      fs.writeFileSync(path.join(dir, "vfs", `${n}.gz`), zlib.gzipSync(bytes, { level: 9 }));
      vfs.push({ token, path: m[1], file: `vfs/${n}.gz`, bytes: bytes.length, sha256: sha(bytes) });
    }
    out += lit.slice(last, st) + token;
    last = en;
    re.lastIndex = en;
  }
  out += lit.slice(last);
  stats.push("VFS");
  return body.slice(0, a) + out + body.slice(b);
}

function tokenize(body, stats) {
  let out = body;
  const glbMarker = "window.__DUCATI_GLB_B64__=";
  const g = out.indexOf(glbMarker);
  if (g >= 0) {
    const q = out[g + glbMarker.length], a = g + glbMarker.length + 1, b = out.indexOf(q, a);
    if (out.slice(a, b) !== GLB_B64) throw Error("embedded GLB differs from assets/models/ducati916.glb");
    out = out.slice(0, a) + "@@GLB_B64@@" + out.slice(b);
    stats.push("GLB");
  }
  for (const [name, text, token] of [["__FRONT_ASSET__", FRONT, "@@FRONT_ASSET@@"], ["__REAR_ASSET__", REAR, "@@REAR_ASSET@@"]]) {
    const mk = `window.${name}=`, i = out.indexOf(mk);
    if (i < 0) continue;
    const a = i + mk.length, b = jsonEnd(out, a);
    if (out.slice(a, b) !== text) throw Error(`${name} differs from the shared asset file`);
    out = out.slice(0, a) + token + out.slice(b);
    stats.push(name);
  }
  const dm = "const DATA=", d = out.indexOf(dm);
  if (d >= 0 && out[d + dm.length] === "{") {
    const a = d + dm.length, b = jsonEnd(out, a), text = out.slice(a, b);
    if (text.length > 1e6) {
      if (!TIRE_DATA) {
        fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
        fs.writeFileSync(DATA_FILE, zlib.gzipSync(Buffer.from(text, "utf8"), { level: 9 }));
        TIRE_DATA = text;
      }
      if (text !== TIRE_DATA) throw Error("tire research DATA differs from the archived reference dataset");
      out = out.slice(0, a) + "@@TIRE_DATA@@" + out.slice(b);
      stats.push("TIRE_DATA");
    }
  }
  return out;
}

const index = fs.existsSync(path.join(ROOT, "reference/index.json"))
  ? JSON.parse(fs.readFileSync(path.join(ROOT, "reference/index.json"), "utf8"))
  : { schema: "lucid-moto.reference-index.v1", builds: [] };

for (const f of files) {
  const raw = fs.readFileSync(f);
  const html = raw.toString("utf8");
  const name = path.basename(f).replace(/^[0-9a-f]{8}-/, "");
  const digest = sha(raw);
  const existing = index.builds.find((b) => b.sha256 === digest);
  if (existing) {
    if (!existing.aliases.includes(name) && existing.file !== name) existing.aliases.push(name);
    console.log(`= ${name} is identical to ${existing.id}; recorded as alias`);
    continue;
  }
  const id = name.replace(/\.html$/i, "");
  const dir = path.join(ROOT, "reference/builds", id);
  fs.mkdirSync(dir, { recursive: true });
  let shell = "", last = 0, n = 0;
  const re = /<script([^>]*)>/g, scripts = [], vfs = [];
  let m;
  while ((m = re.exec(html))) {
    const a = m.index + m[0].length, b = html.indexOf("</script>", a);
    shell += html.slice(last, a) + `@@SCRIPT_${String(n).padStart(2, "0")}@@`;
    const stats = [], body = tokenizeVfs(tokenize(html.slice(a, b), stats), stats, dir, vfs);
    const gz = Buffer.byteLength(body) > 256 * 1024, file = `${String(n).padStart(2, "0")}.js${gz ? ".gz" : ""}`;
    fs.writeFileSync(path.join(dir, file), gz ? zlib.gzipSync(Buffer.from(body, "utf8"), { level: 9 }) : body);
    scripts.push({ index: n, file, tokens: stats, sha256: sha(body), ...(gz ? { gzip: true } : {}) });
    last = b;
    re.lastIndex = b;
    n++;
  }
  shell += html.slice(last);
  fs.writeFileSync(path.join(dir, "shell.html"), shell);
  const man = { schema: "lucid-moto.reference-build.v1", id, file: name, sha256: digest, bytes: raw.length, scripts, ...(vfs.length ? { vfs } : {}) };
  fs.writeFileSync(path.join(dir, "manifest.json"), JSON.stringify(man, null, 2) + "\n");
  index.builds.push({ id, file: name, sha256: digest, bytes: raw.length, aliases: [] });
  console.log(`+ ${id}: ${n} scripts`);
}
index.builds.sort((a, b) => a.id.localeCompare(b.id));
fs.writeFileSync(path.join(ROOT, "reference/index.json"), JSON.stringify(index, null, 2) + "\n");
